import{_ as o,c as e,o as r,ag as s}from"./chunks/framework.bCALENAD.js";const u=JSON.parse('{"title":"浏览器/网络问题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/8part/browser&network.md","filePath":"interview/8part/browser&network.md","lastUpdated":1786362124000}'),i={name:"interview/8part/browser&network.md"};function d(l,t,n,a,c,p){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="浏览器-网络问题" tabindex="-1">浏览器/网络问题 <a class="header-anchor" href="#浏览器-网络问题" aria-label="Permalink to &quot;浏览器/网络问题&quot;">​</a></h1><h2 id="三种会话保持机制" tabindex="-1">三种会话保持机制 <a class="header-anchor" href="#三种会话保持机制" aria-label="Permalink to &quot;三种会话保持机制&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">session 机制保持会话</p><p><strong>存在的问题</strong></p><ul><li>高并发情况下，会占用服务器大量内存。</li><li>分布式（一个业务分成几个子业务，部署在多个服务器）或者集群（一个业务部署在多个服务器）的时候，session 不能共享。</li></ul><p><strong>解决方案</strong></p><ul><li>高并发的时候可以将 session 存储到 redis，如果用户长时间没有访问，将 session 存储到 redis，就减少了服务器的压力。</li><li>分布式或者集群的时候，先通过 redis 来判断用户状态也可以实现 session 共享。</li></ul></div><div class="info custom-block"><p class="custom-block-title">cookie 机制保持会话</p><p><strong>使用方法</strong></p><ul><li>登录验证后，创建登录凭证（比如：用户 id + 登录时间 + 过期时间），将登录凭证进行加密（为了避免暴露信息），加密后写到浏览器的 cookie，以后每次请求都发送 cookie，服务器根据对应的解密算法对其进行验证（或者将加密过的 cookie 内容存储到数据库，请求服务器的时候，服务器在数据库进行查找）。</li></ul><p><strong>存在的问题</strong></p><ul><li>每次访问都提交 cookie，增加请求量。</li><li>其他访问可能需要 cookie（比如说购物车的信息存放在 cookie），浏览器对每个域存储的 cookie 的大小有限制，那么需要控制加密后的凭证。</li></ul></div><div class="info custom-block"><p class="custom-block-title">token 机制保持会话</p><p><strong>使用方法</strong></p><ul><li>cookie 和 session 依赖于浏览器，如果客户端不是浏览器，那么需要手动添加 token（和 cookie 类似，也是登录凭证），将 token 添加到 http header 或者作为参数添加到 url。</li></ul><p><strong>存在的问题</strong></p><ul><li>每次访问的时候手动添加 token。</li><li>和 cookie 的方式一样增加了请求量。</li></ul></div><h2 id="网络五层-七层模型" tabindex="-1">网络五层/七层模型 <a class="header-anchor" href="#网络五层-七层模型" aria-label="Permalink to &quot;网络五层/七层模型&quot;">​</a></h2><p><strong>五层模型：</strong></p><blockquote><p>物理层 → 数据链路层 → 网络层 → 传输层 → 应用层</p></blockquote><p><strong>七层模型：</strong></p><blockquote><p>物理层 → 数据链路层 → 网络层 → 传输层 → 会话层 → 表示层 → 应用层</p></blockquote><table tabindex="0"><thead><tr><th>层次</th><th>主要功能</th><th>数据单位</th><th>典型协议/设备</th></tr></thead><tbody><tr><td><strong>应用层</strong></td><td>为用户应用程序提供网络服务，如网页访问、邮件、文件传输、域名解析</td><td>报文 / 消息</td><td>HTTP、HTTPS、FTP、SMTP、DNS、SSH；代理服务器</td></tr><tr><td><strong>传输层</strong></td><td>提供端到端通信，负责分段、端口寻址、可靠传输或不可靠传输</td><td>报文段 / 数据段</td><td>TCP、UDP；防火墙、网关</td></tr><tr><td><strong>网络层</strong></td><td>负责逻辑寻址和路由选择，把数据从源主机送到目的主机</td><td>分组 / 数据包</td><td>IP、ICMP、ARP；路由器</td></tr><tr><td><strong>数据链路层</strong></td><td>负责相邻节点之间的帧传输、物理寻址、差错检测</td><td>帧</td><td>Ethernet、PPP、Wi-Fi；交换机、网桥</td></tr><tr><td><strong>物理层</strong></td><td>负责比特流在物理介质上的传输，定义电气、机械、功能特性</td><td>比特</td><td>网线、光纤、无线电波；集线器、中继器</td></tr></tbody></table>',11)])])}const h=o(i,[["render",d]]);export{u as __pageData,h as default};
